WITH recent_suppliers AS (SELECT *, LOWER(supplier_name) supplier_name_lower FROM suppliers WHERE rating > 3.2 AND supplier_name LIKE 'G%'), summary AS (SELECT CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END rating_bucket, country, MAX(rating) - MIN(rating) rating_range, COUNT(rating) rating_count FROM recent_suppliers GROUP BY CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END, country) SELECT * FROM summary ORDER BY 4;
